/**
 * Emits a `.htaccess` into the build output so Apache serves this SPA with
 * correct HTTP status codes.
 *
 * The rules are derived from the real route table generated by
 * `vue-router/vite`, so they stay in sync as pages are added or removed:
 *
 *   - known routes          -> served as 200 (the index.html shell, or the
 *                              pre-rendered page with `prerendered`)
 *   - everything else       -> ErrorDocument, served as a genuine 404
 *
 * Without this, deep links such as /ux/solstice/ are hard 404s (no such file
 * on disk), and a naive catch-all rewrite would make every bogus URL a 200.
 *
 * The output also handles being served from two mount points at once. The
 * canonical host serves this directory at `base` (/ux/), while UW URL masking
 * serves the very same directory at the root of a vanity hostname, keeping
 * that hostname in the address bar. Asset URLs are baked with `base` at build
 * time, so masked hosts strip that prefix before anything else runs and every
 * later rule can assume the canonical layout. See the `maskedHosts` option.
 *
 * Vite-only plugin: it reads Vite's resolved `base` via `configResolved` and is
 * scoped to the build and `vite preview` with `apply`, so it has no meaning in
 * plain Rolldown. In preview it serves the build with the same rules, at the
 * site root, so preview URLs carry no `base` prefix.
 *
 * @see https://vite.dev/guide/api-plugin
 */

import fs from "node:fs";
import path from "node:path";

/** The virtual module generated by `vue-router/vite` (`\0vue-router/auto-routes`). */
const ROUTES_MODULE_ID = /vue-router[/\\]auto-routes$/;

/**
 * Output folder for pre-rendered route pages, e.g. `_html/process-guides.html`.
 * Keeping them out of the web root means no route URL is also a physical
 * directory (`process-guides/` holding its child pages), which Apache would
 * otherwise answer with a trailing-slash redirect. Fixing that in place needs
 * `DirectorySlash Off`, which requires `AllowOverride Indexes`.
 */
export const PRERENDER_DIR = "_html";

/** Route paths containing a param, wildcard or regex are left to the 404 handler. */
const DYNAMIC_SEGMENT = /[:*()[\]]/;

/**
 * Pull the `export const routes = [...]` array out of the generated module and
 * evaluate it. Component imports are stripped first so nothing is loaded.
 *
 * @param {string} code source of the virtual auto-routes module
 * @returns {Array<object>} the route records
 */
export function parseRoutes(code) {
  const start = code.indexOf("[", code.indexOf("routes ="));
  if (start === -1) {
    throw new Error("could not locate the routes array");
  }

  let depth = 0;
  let end = -1;
  for (let i = start; i < code.length; i++) {
    if (code[i] === "[") depth++;
    else if (code[i] === "]") {
      depth--;
      if (depth === 0) {
        end = i + 1;
        break;
      }
    }
  }
  if (end === -1) {
    throw new Error("unterminated routes array");
  }

  const literal = code
    .slice(start, end)
    .replace(/component:\s*\(\)\s*=>\s*import\([^)]*\)/g, "component: null")
    .replace(/components:\s*\{[^}]*\}/g, "components: null");

  return new Function(`return ${literal}`)();
}

/**
 * Flatten nested route records into concrete URL paths.
 *
 * @param {Array<object>} routes route records
 * @param {string} [prefix] parent path
 * @returns {Array<string>} absolute, static route paths
 */
export function flattenRoutes(routes, prefix = "") {
  const paths = [];

  for (const route of routes ?? []) {
    const segment = route.path ?? "";
    const full = segment.startsWith("/")
      ? segment
      : `${prefix}/${segment}`.replace(/\/{2,}/g, "/");

    // A route is navigable only if it renders something.
    if (route.component !== undefined || route.components !== undefined) {
      paths.push(full === "" ? "/" : full);
    }

    if (route.children) {
      paths.push(...flattenRoutes(route.children, full));
    }
  }

  return paths;
}

/**
 * Whether a route path falls under one of the excluded prefixes.
 *
 * @param {string} path absolute route path
 * @param {Array<string>} exclude path prefixes
 * @returns {boolean}
 */
export function isExcluded(path, exclude = []) {
  return exclude.some((p) => path === p || path.startsWith(`${p}/`));
}

/**
 * Reduce route paths to the static, public pages: absolute, without a
 * trailing slash, de-duplicated, and with dynamic routes and exclusions
 * removed. This is the list that is pre-rendered and whitelisted.
 *
 * @param {Array<string>} paths absolute route paths
 * @param {Array<string>} [exclude] path prefixes to leave out
 * @returns {Array<string>} sorted paths, e.g. `["/", "/xd-team"]`
 */
export function staticPaths(paths, exclude = []) {
  const result = new Set();

  for (const path of paths) {
    if (DYNAMIC_SEGMENT.test(path)) continue;
    if (isExcluded(path, exclude)) continue;

    result.add(`/${path.replace(/^\/+/, "").replace(/\/+$/, "")}`);
  }

  return [...result].sort();
}

/**
 * Turn route paths into the rewrite alternation branches used in the
 * generated `.htaccess`: the static paths, base-relative and regex-escaped.
 *
 * @param {Array<string>} paths absolute route paths
 * @param {Array<string>} [exclude] path prefixes to leave out of the whitelist
 * @returns {Array<string>} sorted regex branches
 */
export function toRewriteBranches(paths, exclude = []) {
  return (
    staticPaths(paths, exclude)
      .map((path) => path.slice(1))
      // The site root is served by index.html directly, so it needs no rule.
      .filter((relative) => relative !== "")
      .map((relative) => relative.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
  );
}

/**
 * Build the `RewriteCond` lines that limit a rule to the masked hostnames.
 * Conditions are OR-ed, so the last one carries no `OR` flag.
 *
 * @param {Array<string>} hosts masked hostnames
 * @returns {Array<string>} condition lines
 */
export function hostConditions(hosts) {
  return hosts.map((host, i) => {
    const flags = i < hosts.length - 1 ? "NC,OR" : "NC";
    // `=` is a lexical match, so dots need no escaping.
    return `  RewriteCond %{HTTP_HOST} =${host} [${flags}]`;
  });
}

/**
 * Render the `.htaccess` body.
 *
 * @param {Array<string>} branches regex branches for known routes
 * @param {string} base deployment base path, e.g. `/ux/`
 * @param {object} [options]
 * @param {Array<string>} [options.maskedHosts] hostnames serving this
 *   directory at their root rather than at `base`
 * @param {string} [options.allowOrigin] value for `Access-Control-Allow-Origin`
 * @param {boolean} [options.prerendered] routes were pre-rendered to
 *   `<PRERENDER_DIR>/<route>.html` and the 404 page to `404.html` (vite-ssg)
 * @returns {string} file contents
 */
export function renderHtaccess(branches, base, options = {}) {
  const { maskedHosts = [], allowOrigin, prerendered = false } = options;

  const shell = `${base}index.html`;
  const errorPage = prerendered ? `${base}404.html` : shell;
  const routeGroup = branches.length > 0 ? branches.join("|") : "$^";
  // `/ux/` -> `ux`: the prefix masked hosts have to strip.
  const prefix = base.replace(/^\/+/, "").replace(/\/+$/, "");

  const sections = [
    `# Generated at build time by vite-plugin-htaccess.js — do not edit.
# Rules are derived from the vue-router route table; rebuild to regenerate.`,
  ];

  const rules = ["  RewriteEngine On"];

  if (maskedHosts.length > 0 && prefix !== "") {
    rules.push(
      `
  # These hosts serve this directory at their root, but asset URLs are baked
  # with the "${base}" base at build time. Strip the prefix so they resolve;
  # every rule below can then assume the canonical layout.
${hostConditions(maskedHosts).join("\n")}
  RewriteRule ^${prefix}/(.*)$ /$1 [L]`,
    );
  }

  const passthrough = `
  # Serve real files and directories as-is (assets, images, favicon).
  RewriteCond %{REQUEST_FILENAME} -f [OR]
  RewriteCond %{REQUEST_FILENAME} -d
  RewriteRule ^ - [L]`;

  if (prerendered) {
    // Routes come before the passthrough so a legacy file or directory with
    // the same name as a route cannot shadow the page.
    rules.push(
      `
  # Known routes: serve the pre-rendered page with a 200.
  RewriteRule ^(${routeGroup})/?$ ${base}${PRERENDER_DIR}/$1.html [L]
${passthrough}`,
    );
  } else {
    rules.push(
      `${passthrough}

  # Known SPA routes: serve the app shell with a 200.
  RewriteRule ^(${routeGroup})/?$ ${shell} [L]`,
    );
  }

  sections.push(`<IfModule mod_rewrite.c>\n${rules.join("\n")}\n</IfModule>`);

  sections.push(
    `# Anything else: serve the ${prerendered ? "pre-rendered 404 page" : "app shell"}, but with a real 404 status so
# crawlers and monitoring see the failure. The router's catch-all renders the
# 404 page. The internal redirect re-enters the rules above, so masked hosts
# have the prefix stripped and resolve this too.
ErrorDocument 404 ${errorPage}`,
  );

  if (allowOrigin) {
    sections.push(
      `<IfModule mod_headers.c>
  Header set Access-Control-Allow-Origin "${allowOrigin}"
</IfModule>`,
    );
  }

  return `${sections.join("\n\n")}\n`;
}

/**
 * Render `sitemap.xml` for the public pages.
 *
 * @param {Array<string>} paths static route paths, e.g. `["/", "/xd-team"]`
 * @param {string} siteUrl canonical site URL without a trailing slash, e.g.
 *   `https://depts.washington.edu/ux`
 * @returns {string} file contents
 */
export function renderSitemap(paths, siteUrl) {
  const escape = (text) =>
    text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

  const urls = paths.map(
    (path) => `  <url><loc>${escape(`${siteUrl}${path}`)}</loc></url>`,
  );

  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join("\n")}
</urlset>
`;
}

/**
 * Render `robots.txt`. Crawlers only read it at a host's root, so it takes
 * effect on masked hosts (which serve this directory at their root) but not
 * under `base` on the canonical host.
 *
 * @param {string} siteUrl canonical site URL without a trailing slash
 * @returns {string} file contents
 */
export function renderRobots(siteUrl) {
  return `# Generated at build time by vite-plugin-htaccess.js — do not edit.
# All crawlers are welcome, including search and AI answer engines.
User-agent: *
Allow: /

Sitemap: ${siteUrl}/sitemap.xml
`;
}

/**
 * Map a `vite preview` request onto the build output the way the generated
 * `.htaccess` does on a masked host, so the build can be previewed at the
 * site root (`/xd-team`) even though asset URLs are baked with `base`
 * (`/ux/assets/…`).
 *
 * @param {string} pathname request path, without the query string
 * @param {string} base deployment base path, e.g. `/ux/`
 * @param {(path: string) => boolean} isFile whether a path relative to the
 *   output directory (with a leading slash) is an existing file
 * @returns {{ path: string, status: number }} the file to serve
 */
export function resolvePreviewPath(pathname, base, isFile) {
  let path = pathname;

  // strip the baked-in base, like the masked-host rule
  const prefix = base.replace(/\/+$/, "");
  if (prefix !== "" && (path === prefix || path.startsWith(`${prefix}/`))) {
    path = path.slice(prefix.length) || "/";
  }

  // real files as-is (assets, images, favicon)
  if (path !== "/" && isFile(path)) return { path, status: 200 };

  const route = path.replace(/\/+$/, "");
  if (route === "") return { path: "/index.html", status: 200 };

  // known routes: their pre-rendered page
  const page = `/${PRERENDER_DIR}${route}.html`;
  if (isFile(page)) return { path: page, status: 200 };

  return { path: "/404.html", status: 404 };
}

/**
 * @param {object} [options]
 * @param {string} [options.base] deployment base path; defaults to Vite's `base`
 * @param {Array<string>} [options.exclude] route prefixes kept out of the
 *   whitelist. These still render client-side but respond 404, which keeps them
 *   out of search indexes.
 * @param {Array<string>} [options.maskedHosts] hostnames that serve this
 *   directory at their root instead of at `base`, e.g. a masked vanity domain.
 * @param {string} [options.allowOrigin] value for `Access-Control-Allow-Origin`
 * @param {boolean} [options.prerendered] target the pages pre-rendered by
 *   vite-ssg (`<route>.html`, `404.html`) instead of the `index.html` shell
 * @param {string} [options.siteUrl] canonical site URL without a trailing
 *   slash; when set, `sitemap.xml` and `robots.txt` are emitted as well
 * @returns {import("vite").Plugin}
 */
export default function htaccess({
  base,
  exclude = [],
  maskedHosts = [],
  allowOrigin,
  prerendered = false,
  siteUrl,
} = {}) {
  let resolvedBase = base;
  let routePaths = [];
  let outDir;

  return {
    // shows up in warnings and errors
    name: "vite-plugin-htaccess",
    // build: emit .htaccess. preview: serve the build with the same rules.
    apply: (_config, env) => env.command === "build" || env.isPreview,

    configResolved(config) {
      resolvedBase ??= config.base;
      outDir = path.resolve(config.root, config.build.outDir);
    },

    configurePreviewServer(server) {
      if (!prerendered) return;

      const isFile = (file) =>
        fs
          .statSync(path.join(outDir, file), { throwIfNoEntry: false })
          ?.isFile() ?? false;

      // registered before Vite's static file handler, so it sees every request
      server.middlewares.use((req, res, next) => {
        const [pathname, query] = req.url.split("?");
        const target = resolvePreviewPath(
          decodeURIComponent(pathname),
          resolvedBase,
          isFile,
        );

        if (target.status === 404) {
          res.statusCode = 404;
          res.setHeader("Content-Type", "text/html; charset=utf-8");
          res.end(fs.readFileSync(path.join(outDir, target.path)));
          return;
        }

        req.url = query === undefined ? target.path : `${target.path}?${query}`;
        next();
      });
    },

    transform: {
      filter: {
        id: ROUTES_MODULE_ID,
      },
      handler(code) {
        try {
          routePaths = flattenRoutes(parseRoutes(code));
        } catch (error) {
          this.warn(`could not read the route table: ${error.message}`);
        }

        // read-only: the module is passed through untouched
        return null;
      },
    },

    generateBundle() {
      if (routePaths.length === 0) {
        this.warn("no routes found; skipping .htaccess generation");
        return;
      }

      const branches = toRewriteBranches(routePaths, exclude);

      this.emitFile({
        type: "asset",
        fileName: ".htaccess",
        source: renderHtaccess(branches, resolvedBase, {
          maskedHosts,
          allowOrigin,
          prerendered,
        }),
      });

      if (siteUrl) {
        const site = siteUrl.replace(/\/+$/, "");

        this.emitFile({
          type: "asset",
          fileName: "sitemap.xml",
          source: renderSitemap(staticPaths(routePaths, exclude), site),
        });
        this.emitFile({
          type: "asset",
          fileName: "robots.txt",
          source: renderRobots(site),
        });
      }
    },
  };
}
